    $url = str_replace('%kernel.environment%', $env, $url);

    if (strpos($url, 'sqlite:///') === 0) {
        return 'sqlite:' . substr($url, strlen('sqlite:///'));
    }

    // MySQL – puvodni produkce, uz se nepouziva
    if (strpos($url, 'mysql://') === 0) {
